/* ---------- Tutorial "🔁 Swap drawings (practice)": two drawings of the same girl (art by the user), swapped on the
   timeline. The practice file puts face A on frame 1 and face B on frame 4; the steps add both to the swap bar and
   swap them on later frames. SWAP_FACES = JPEG data (340 px wide). Added to TUTORIALS after 'fox'. ---------- */
const SWAP_FACES = ['data:image/jpeg;base64,', 'data:image/jpeg;base64,'];
let swapTutDoc = null;
async function swapTutOpen() {
  const imgs = await Promise.all(SWAP_FACES.map(loadImage));
  newDocument(400, 400, 12, 8, false, 'Swap — practice');
  const l = state.layers.find(x => !x.paper) || (CMD.layerAdd(), activeLayer());
  l.name = 'Face'; state.activeId = l.id;
  const put = (f, im) => { if (!l.cels.has(f)) l.cels.set(f, makeCel(true)); const c = l.cels.get(f), g = c.getContext('2d'), k = Math.min(380 / im.width, 380 / im.height); g.clearRect(0, 0, 400, 400); g.drawImage(im, 200 - im.width * k / 2, 200 - im.height * k / 2, im.width * k, im.height * k); c._ink = true; c._sv = (c._sv || 0) + 1; };
  put(0, imgs[0]); put(3, imgs[1]);
  history.undo.length = 0; history.redo.length = 0; dirty = false;
  if (state.mode !== 'anim') setMode('anim', true);
  gotoFrame(0, true); bindAll(state.frame); refreshAll(); fit(); if (typeof syncTab === 'function') syncTab();
  swapTutDoc = state.name;
}
async function swapTutEnsure() { if (state.name !== swapTutDoc) await swapTutOpen(); else if (state.mode !== 'anim') setMode('anim', true); }
const swapTutLayer = () => state.layers.find(l => l.name === 'Face') || activeLayer();
function swapTutAdd(f, name) { const l = swapTutLayer(); state.activeId = l.id; gotoFrame(f, true); if (!swapsOf(l).some(s => s.name === name)) swapAdd(l, name); refreshAll(); }
function swapTutUse() { const l = swapTutLayer(), s = swapsOf(l); if (s.length < 2) { swapTutAdd(0, 'Face 1'); swapTutAdd(3, 'Face 2'); } const L = swapsOf(l); gotoFrame(6, true); swapUse(l, L[0].id); gotoFrame(9, true); swapUse(l, L[1].id); gotoFrame(6, true); refreshAll(); }
function installSwapTutorial() {
  Object.assign(CMD, { swapPractice: () => swapTutOpen(), tut_swap: () => tutStart('swap') });
  const A = MENUS.find(m => m[0] === 'Animation'); if (A) A[1].push(['🔁 Swap drawings tutorial (practice file)', 'tut_swap']);
  const at = TUTORIALS.findIndex(t => t.id === 'fox');
  TUTORIALS.splice(at < 0 ? TUTORIALS.length : at + 1, 0, { id: 'swap', cat: 'Animation & rigging', icon: '🔁', title: 'Swap drawings (practice)', desc: 'Change a face (or a hand, eyes…) during an animation in one tap.', steps: [
    { el: '#viewport', pre: swapTutEnsure, t: '🔁 Your practice file', x: 'A new tab opened in the Animation workspace with <b>two drawings of the same girl</b>: a calm face on <b>frame 1</b> and an excited face on <b>frame 4</b>. Swap drawings lets you reuse them on any frame.' },
    { el: ['#swapBar .sw-add', '#swapBar'], pre: async () => { await swapTutEnsure(); gotoFrame(0, true); refreshAll(); }, t: '1. Add the first drawing', x: 'On <b>frame 1</b>, tap <b>＋</b> in the 🔁 Swap bar (above the timeline) and name it, e.g. "Face 1".', demo: ['Show me', () => swapTutAdd(0, 'Face 1')] },
    { el: ['#swapBar .sw-add', '#swapBar'], pre: async () => { await swapTutEnsure(); gotoFrame(3, true); refreshAll(); }, t: '2. Add the second drawing', x: 'Go to <b>frame 4</b> and tap <b>＋</b> again: "Face 2". Both drawings are now in the bar.', demo: ['Show me', () => swapTutAdd(3, 'Face 2')] },
    { el: ['#swapBar .sw-item', '#swapBar'], pre: swapTutEnsure, t: '3. Swap on any frame', x: 'Go to another frame (e.g. 7) and <b>tap a drawing</b> in the bar: it is put on that frame. The frame keeps its position, bones and tweens. <b>Alt+]</b> / <b>Alt+[</b> = next / previous drawing.', demo: ['Show me', swapTutUse] },
    { el: ['#swapBar .sw-upd', '#swapBar'], pre: swapTutEnsure, t: '4. Edit once, update everywhere', x: 'Changed a drawing (a new eye, a fixed line)? On that frame tap <b>⟳ Update everywhere</b>: every frame that uses it gets the change.' },
    { el: ['#btnPlay', '#timeline'], pre: swapTutEnsure, t: '5. Play it', x: 'Press <b>Play</b> (Enter): the face changes on the frames where you swapped. Use the same idea for hands (open / closed), eyes (open / closed) and mouths.', demo: ['Play', () => { gotoFrame(0, true); CMD.play(); }] }
  ] });
}
